ssize_t decode_compact_pixels(size_t number_compact_pixels, const unsigned char* compact_pixels, ssize_t depth, size_t number_pixels, unsigned char* pixels) {
    size_t i = 0, j = 0;
    ssize_t count = 0;

    if (!compact_pixels || !pixels || depth < 1 || depth > 4)
        return -1;

    while (i < number_compact_pixels && j < number_pixels) {
        switch (depth) {
            case 1:
                for (size_t k = 0; k < 8 && i < number_compact_pixels && j < number_pixels; ++k, ++i, ++j) {
                    pixels[j] = (compact_pixels[i] >> (7 - k)) & 0x01;
                }
                break;
            case 2:
                for (size_t k = 0; k < 4 && i < number_compact_pixels && j < number_pixels; ++k, ++i, ++j) {
                    pixels[j] = (compact_pixels[i] >> (6 - k * 2)) & 0x03;
                }
                break;
            case 4:
                for (size_t k = 0; k < 2 && i < number_compact_pixels && j < number_pixels; ++k) {
                    pixels[j++] = (compact_pixels[i] >> 4) & 0x0F;
                    if (j < number_pixels)
                        pixels[j++] = compact_pixels[i++] & 0x0F;
                }
                break;
            default:
                return -1;
        }
    }

    return count;
}

ssize_t decode_compact_pixels(size_t number_compact_pixels, const unsigned char* compact_pixels, ssize_t depth, size_t number_pixels, unsigned char* pixels) {
    size_t i = 0, j = 0;

    while (i < number_compact_pixels && j < number_pixels) {
        unsigned char byte = compact_pixels[i];

        switch (depth) {
            case 1:
                // 8 pixels per byte at 1 bit depth
                for (int bit = 0; bit < 8 && j < number_pixels; bit++, byte >>= 1) {
                    pixels[j++] = (unsigned char)((byte & 0x01) ? 255 : 0);
                }
                break;
            case 2:
                // 4 pixels per byte at 2 bits depth
                for (int bit = 0; bit < 4 && j < number_pixels; bit++, byte >>= 2) {
                    pixels[j++] = (unsigned char)((byte & 0x03) * 0x55); // Scale to 0-255
                }
                break;
            case 4:
                // 2 pixels per byte at 4 bits depth
                for (int bit = 0; bit < 2 && j < number_pixels; bit++, byte >>= 4) {
                    pixels[j++] = (unsigned char)((byte & 0x0F) * 0x11); // Scale to 0-255
                }
                break;
            default:
                return -1; // Invalid depth
        }

        i++;
    }

    return (ssize_t)j;
}

ssize_t decode_compact_pixels(size_t number_compact_pixels, const unsigned char* compact_pixels, ssize_t depth, size_t number_pixels, unsigned char* pixels) {
    size_t i, j = 0;
    size_t out_index = 0;

    switch (depth) {
        case 1:
            for (i = 0; i < number_compact_pixels && out_index < number_pixels; i++) {
                unsigned char byte = compact_pixels[i];
                for (size_t bit = 0; bit < 8 && out_index < number_pixels; bit++) {
                    pixels[out_index++] = (byte >> (7 - bit)) & 0x01;
                }
            }
            break;
        case 2:
            for (i = 0; i < number_compact_pixels && out_index < number_pixels; i++) {
                unsigned char byte = compact_pixels[i];
                for (size_t bit = 0; bit < 4 && out_index < number_pixels; bit++) {
                    pixels[out_index++] = (byte >> (6 - bit * 2)) & 0x03;
                }
            }
            break;
        case 4:
            for (i = 0; i < number_compact_pixels && out_index < number_pixels; i++) {
                unsigned char byte = compact_pixels[i];
                for (size_t bit = 0; bit < 2 && out_index < number_pixels; bit++) {
                    pixels[out_index++] = (byte >> (4 - bit * 4)) & 0x0F;
                }
            }
            break;
        default:
            return -1;
    }

    return (ssize_t)out_index;
}

ssize_t decode_pixel_data(size_t number_compact_pixels, const unsigned char* compact_pixels, ssize_t depth, size_t number_pixels, unsigned char* pixels) {
    size_t i = 0;
    size_t j = 0;

    while (i < number_compact_pixels && j < number_pixels) {
        switch (depth) {
            case 1:
                for (size_t k = 0; k < 8 && i < number_compact_pixels && j < number_pixels; ++k, ++j) {
                    pixels[j] = (compact_pixels[i] >> (7 - k)) & 0x01;
                }
                ++i;
                break;
            case 2:
                for (size_t k = 0; k < 4 && i < number_compact_pixels && j < number_pixels; ++k, ++j) {
                    pixels[j] = (compact_pixels[i] >> (6 - (2 * k))) & 0x03;
                }
                ++i;
                break;
            case 4:
                for (size_t k = 0; k < 2 && i < number_compact_pixels && j < number_pixels; ++k, ++j) {
                    pixels[j] = (compact_pixels[i] >> (4 * (1 - k))) & 0x0F;
                }
                ++i;
                break;
            default:
                return -1;
        }
    }
    return (ssize_t)j;
}

ssize_t decode_compact_pixels(size_t number_compact_pixels, const unsigned char* compact_pixels, ssize_t depth, size_t number_pixels, unsigned char* pixels) {
    size_t src_index = 0;
    size_t dst_index = 0;

    while (number_compact_pixels > 0 && number_pixels > 0) {
        switch (depth) {
            case 1:
                for (size_t i = 0; i < 8 && number_compact_pixels > 0 && number_pixels > 0; ++i) {
                    pixels[dst_index++] = (compact_pixels[src_index] >> (7 - i)) & 0x01;
                    --number_compact_pixels;
                    --number_pixels;
                }
                ++src_index;
                break;
            case 2:
                for (size_t i = 0; i < 4 && number_compact_pixels > 0 && number_pixels > 0; ++i) {
                    pixels[dst_index++] = (compact_pixels[src_index] >> (6 - (i * 2))) & 0x03;
                    --number_compact_pixels;
                    --number_pixels;
                }
                ++src_index;
                break;
            case 4:
                for (size_t i = 0; i < 2 && number_compact_pixels > 0 && number_pixels > 0; ++i) {
                    pixels[dst_index++] = (compact_pixels[src_index] >> ((1 - i) * 4)) & 0x0F;
                    --number_compact_pixels;
                    --number_pixels;
                }
                ++src_index;
                break;
            default:
                return -1; // Invalid depth
        }
    }

    return (ssize_t)(dst_index);
}
